#!/usr/bin/env python3
from __future__ import annotations
import pathlib, sys
ROOT=pathlib.Path(__file__).resolve().parents[1]
def text(p): return (ROOT/p).read_text()
checks=[]
def check(n,c): checks.append((n,c))
cargo=text('Cargo.toml'); core=text('crates/sparkbridge-core/src/lib.rs'); protocol=text('crates/sparkbridge-protocol/src/lib.rs'); cand=text('crates/sparkbridge-candidate/src/lib.rs'); promo=text('crates/sparkbridge-promotion/src/lib.rs'); server=text('apps/sparkbridge-server/src/main.rs'); store=text('apps/sparkbridge-server/src/store.rs'); executor=text('apps/sparkbridge-executor/src/main.rs'); cli=text('apps/sparkbridge-cli/src/main.rs'); snap=text('crates/sparkbridge-snapshot/src/lib.rs')
check('workspace version 0.12.0','version = "0.12.0"' in cargo)
check('protocol is 1.10','PROTOCOL_MINOR: u16 = 10' in protocol)
check('candidate and promotion crates are workspace members','crates/sparkbridge-candidate' in cargo and 'crates/sparkbridge-promotion' in cargo)
check('candidate feature negotiation exists','ITERATION_5_CANDIDATES' in core and 'CandidateWorkspaces' in core and 'TransactionalPromotion' in core)
check('candidate operations are structured','enum CandidateOperation' in cand and 'CreateFile' in cand and 'ModifyFile' in cand and 'DeleteFile' in cand and 'RenameFile' in cand)
check('candidate modifications bind expected base digests','expected_base_digest' in cand)
check('candidate replacement data is content addressed','content_digest' in cand and 'validate_content' in cand)
check('candidate manifest is immutable CAS object','CandidateManifest' in cand and 'cas.put_bytes' in cand)
check('candidate paths reject traversal','validate_logical_path' in cand and 'component == ".."' in cand)
check('candidate paths reject case double-touch','candidate touches a path more than once or case-collides' in cand)
check('candidate creation is loopback admin surface','/api/v1/admin/candidates' in server and 'admin_create_candidate' in server)
check('candidate inline contents enter CAS before manifest','BASE64.decode' in server and 'state.cas.put_bytes' in server)
check('candidate validates against immutable base snapshot','get_snapshot' in store and 'validate_candidate(&base' in server)
check('candidate registry is durable SQLite','CREATE TABLE IF NOT EXISTS candidates' in store and 'register_candidate' in store)
check('schema is v9 with additive migration','SCHEMA_VERSION: u32 = 9' in store and 'PRAGMA user_version = 9' in store)
check('executor explicit promote command exists','promote: Option<String>' in executor and 'promote_candidate' in executor)
check('executor supports dry-run promotion','dry_run: bool' in executor and 'PromotionOutcome::DryRun' in executor)
check('candidate retrieval is mTLS and workspace bound','/api/v1/nodes/{id}/candidates/{candidate_id}' in server and 'candidate validation requires this executor to advertise the same logical workspace' in server)
check('promotion fetches candidate and base from CAS','fetch_cas_object' in executor and 'base_manifest_digest' in executor)
check('three-way merge exists','conservative_three_way' in promo and 'overlapping or non-text three-way changes' in promo)
check('merge only auto-resolves disjoint changes','ours.end <= theirs.start' in promo and 'theirs.end <= ours.start' in promo)
check('promotion precommit re-snapshots live workspace','let precommit = snapshot_workspace' in executor and 'WORKSPACE_CHANGED' in executor)
check('workspace generation head is monotonic','WorkspaceHead' in executor and 'saturating_add(1)' in executor and 'workspace-head.json' in executor)
check('snapshot registration now uses workspace generation','source_generation: head.generation' in executor)
check('promotion uses exclusive workspace lock','promotion.lock' in promo and 'WorkspacePromotionLock::acquire' in executor)
check('crash recovery runs after lock acquisition','let promotion_lock = WorkspacePromotionLock::acquire(&workspace)?;' in executor and executor.index('let promotion_lock = WorkspacePromotionLock::acquire(&workspace)?;') < executor.index('recover_incomplete_transactions(&workspace, &cas)?;'))
check('dry-run promotion does not mutate the live workspace','if !dry_run { recover_incomplete_transactions(&workspace, &cas)?; }' in executor and 'if !dry_run { save_workspace_head(&workspace, &head)?; }' in executor)
check('promotion journals before applying','journal.state="applying"' in promo and 'write_journal' in promo)
check('promotion backs up every touched path','collect_paths' in promo and 'backup_path' in promo)
check('failed promotion rolls back','rollback(workspace' in promo and 'promotion failed; rollback completed' in promo)
check('last-moment digest checks protect user edits','verify_expected' in promo and 'live file changed during promotion' in promo)
check('promotion rejects symlink ancestors','symlink ancestor blocks promotion' in promo)
check('writes use temporary file and rename','sparkbridge-' in promo and 'create_new(true)' in promo and 'fs::rename(&tmp,path)' in promo)
check('promotion reports applied/conflict/dry-run/failed','enum PromotionOutcome' in protocol and all(x in protocol for x in ['Applied','Conflict','DryRun','Failed']))
check('promotion reports are authenticated and workspace-bound','register_promotion' in server and 'promotion does not match candidate node/workspace' in server)
check('reported result manifest must exist in DGX CAS','reported result manifest is not present in server CAS' in server)
check('promotion registry is durable SQLite','CREATE TABLE IF NOT EXISTS promotions' in store and 'list_promotions' in store)
check('admin can list candidate and promotion records','CandidatesCommand' in cli and 'PromotionsCommand' in cli)
check('CLI patch files reference local content files','content_file: PathBuf' in cli and 'encode_patch_operations' in cli)
check('snapshot excludes SparkBridge transaction metadata','rel == ".sparkbridge"' in snap)
check('promotion crate does not execute remote commands','std::process::Command' not in promo)
failed=[n for n,c in checks if not c]
for n,c in checks: print(('PASS' if c else 'FAIL')+': '+n)
if failed:
 print(f'\n{len(failed)} candidate/promotion invariant(s) failed',file=sys.stderr); sys.exit(1)
print(f'\nCandidate + Promotion audit passed: {len(checks)} invariants')
